export const Schema = z.object({
    世界: z.object({
        当前日期: z.string(),
        当前场景: z.string(),
    }),
    梁思申: z.object({
        好感度: z.coerce.number().transform(v => _.clamp(v, 0, 200)),
        关系阶段: z.enum(['初识', '动摇', '越界', '沦陷']),
        背德感: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
        是否已越界: z.coerce.boolean(),
    }),
    宋运辉: z.object({
        察觉度: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
    }),
});
